CREATE TABLE "demo_sample_draft" ( "id" varchar(36) NOT NULL PRIMARY KEY, "created_by" varchar(36) NOT NULL, "target_key" varchar(36) NOT NULL, "sample_id" varchar(36), "base_version" integer, "session_id" varchar(36) NOT NULL, "revision" integer NOT NULL, "code" varchar(32) NOT NULL, "title" varchar(120) NOT NULL, "note" text NOT NULL, "has_changes" boolean NOT NULL, "updated_at" integer NOT NULL, CONSTRAINT "uq_demo_draft_owner_target" UNIQUE ("created_by", "target_key"), CHECK ("revision" >= 0), CHECK ("base_version" >= 1) );
